-- Quoted schema and type names holding a dot, array casts to missing types,
-- SQL/JSON length modifiers, pseudo-type casts and %TYPE routine signatures.
CREATE SCHEMA "My.Schema";
CREATE TYPE "My.Schema".t AS (a int4);
CREATE TYPE "dotted.type" AS ENUM ('x');
SELECT NULL::"My.Schema".t;
SELECT '(1)'::"My.Schema"."t";
SELECT 'x'::"dotted.type";
SELECT 'x'::public."dotted.type";
CREATE TABLE "My.Schema".tab (x "My.Schema".t, y "dotted.type");
SELECT pg_typeof(x), pg_typeof(y) FROM "My.Schema".tab;
SELECT 'x'::"My.Schema".nope;
SELECT 'x'::nope.t;
SELECT 'x'::"nope.t";
SELECT ARRAY[]::nope.t[];
SELECT ARRAY[1, 2]::nope.t[];
SELECT ARRAY[]::"My.Schema".t[];
SELECT ARRAY[1]::nope[];
SELECT JSON_SERIALIZE('{"a":1}' RETURNING varchar(3));
SELECT JSON_SERIALIZE('{"a":1}' RETURNING varchar(7));
SELECT JSON_SERIALIZE('{"a":1}' RETURNING char(3));
SELECT JSON_SERIALIZE('{"a":1}' RETURNING char(9));
SELECT JSON_SERIALIZE('"abc  "' RETURNING varchar(5));
SELECT JSON_SERIALIZE('{"a":1}' RETURNING int4);
SELECT JSON_ARRAY(1, 2 RETURNING varchar(3));
SELECT JSON_ARRAY(1, 2 RETURNING varchar(5));
SELECT JSON_OBJECT('a': 1 RETURNING varchar(3));
SELECT JSON_ARRAYAGG(g RETURNING varchar(3)) FROM generate_series(1, 3) g;
SELECT JSON_ARRAYAGG(g RETURNING varchar(7)) FROM generate_series(1, 3) g;
SELECT JSON_OBJECTAGG(g: g RETURNING varchar(3)) FROM generate_series(1, 3) g;
SELECT 1::trigger;
SELECT NULL::trigger;
SELECT 'x'::trigger;
SELECT 'x'::text::trigger;
SELECT NULL::int::trigger;
SELECT 1::event_trigger;
SELECT 1.5::language_handler;
CREATE TABLE ty (a int4, b text, c varchar(20), d numeric(5,2));
CREATE FUNCTION tf(p ty.a%TYPE) RETURNS ty.b%TYPE LANGUAGE sql AS 'SELECT p::text';
SELECT tf(3);
CREATE FUNCTION tf2(p ty.nope%TYPE) RETURNS int LANGUAGE sql AS 'SELECT 1';
CREATE FUNCTION tf3(p nope.a%TYPE) RETURNS int LANGUAGE sql AS 'SELECT 1';
CREATE FUNCTION tf4(ty.c%TYPE, public.ty.d%TYPE) RETURNS int LANGUAGE sql AS 'SELECT 1';
CREATE FUNCTION tf5(p a%TYPE) RETURNS int LANGUAGE sql AS 'SELECT 1';
SELECT pg_get_function_arguments('tf'::regproc), pg_get_function_result('tf'::regproc), pg_get_function_arguments('tf4'::regproc);
CREATE FUNCTION tf6(INOUT x ty.a%TYPE) LANGUAGE sql AS 'SELECT x';
SELECT tf6(5);
SELECT * FROM generate_series(1, 2) AS g(x nope);
SELECT * FROM generate_series(1, 2) AS g(x int);
SELECT * FROM json_to_record('{"a":1}') AS r(a int);
